DG.put("hikaaitaan/9",{"n":9,"title":null,"title_roman":null,"page":2615,"blocks":[{"type":"verse","number":[1],"number_text":"੧।","page":2615,"lines":[{"gurmukhi":"ਗਫ਼ੂਰੋ ਗੁਨਹ ਬਖ਼ਸ਼ ਗਾਫ਼ਲ ਕੁਸ਼ ਅਸਤ।","roman":"Gafooro gunah bakhash gaafal kush asat |","meaning_en":"","page":2615},{"gurmukhi":"ਜਹਾਂ ਰਾ ਤੁਈਂ ਬਸਤੁ ਈਂ ਬੰਦੁਬਸਤ। ੧।","roman":"Jahaan raa tueen bastu een bandubsat | 1 |","meaning_en":"","page":2615}]},{"type":"verse","number":[2],"number_text":"੨।","page":2615,"lines":[{"gurmukhi":"ਨ ਪਿਸਰੋ ਨ ਮਾਦਰ ਬਿਰਾਦਰ ਪਿਦਰ।","roman":"Na pisro na maadar biraadar pidar |","meaning_en":"","page":2615},{"gurmukhi":"ਨ ਦਾਮਾਦੁ ਦੁਸ਼ਮਨ ਨ ਯਾਰੇ ਦਿਗਰ। ੨।","roman":"Na daamaadu dushman na yaare digar | 2 |","meaning_en":"","page":2615}]},{"type":"verse","number":[3],"number_text":"੩।","page":2615,"lines":[{"gurmukhi":"ਸ਼ੁਨੀਦਮ ਸੁਖ਼ਨ ਸ਼ਾਹਿ ਮਾਯੰਦਰਾਂ।","roman":"Shuneedam sukhan shaahi maayandraan |","meaning_en":"","page":2615},{"gurmukhi":"ਕਿ ਰੌਸ਼ਨ ਦਿਲੋ ਨਾਮ ਰੌਸ਼ਨ ਜ਼ਮਾਂ। ੩।","roman":"Ki raushan dilo naam raushan zamaan | 3 |","meaning_en":"","page":2615}]},{"type":"verse","number":[4],"number_text":"੪।","page":2615,"lines":[{"gurmukhi":"ਕਿ ਨਾਮਸ਼ ਵਜ਼ੀਰਸਤ ਸਾਹਿਬ ਸ਼ਊਰ।","roman":"Ki naamash vazeersat saahib shaoor |","meaning_en":"","page":2615},{"gurmukhi":"ਕਿ ਸਾਹਿਬ ਦਿਮਾਗ ਅਸਤ ਜ਼ਾਹਰ ਜ਼ਹੂਰ। ੪।","roman":"Ki saahib dimaag asat zaahar zahoor | 4 |","meaning_en":"","page":2615}]},{"type":"verse","number":[5],"number_text":"੫।","page":2615,"lines":[{"gurmukhi":"ਕਿ ਪਿਸਰੇ ਅਜ਼ਾਂ ਬੂਦ ਰੌਸ਼ਨ ਜ਼ਮੀਰ।","roman":"Ki pisre azaan bood raushan zameer |","meaning_en":"","page":2615},{"gurmukhi":"ਕਿ ਹੁਸਨਲ ਜਮਾਲ ਅਸਤ ਸਾਹਿਬ ਅਮੀਰ। ੫।","roman":"Ki husnal jamaal asat saahib ameer | 5 |","meaning_en":"","page":2615}]},{"type":"verse","number":[6],"number_text":"੬।","page":2615,"lines":[{"gurmukhi":"ਕਿ ਰੌਸ਼ਨ ਦਿਲੇ ਸ਼ਾਹਿ ਓ ਨਾਮ ਬੂਦ।","roman":"Ki raushan dile shaahi o naam bood |","meaning_en":"","page":2615},{"gurmukhi":"ਅਦੂਰਾ ਜ਼ਿਮਰਦੀ ਬਰ ਆਵੁਰਦ ਦੂਦ। ੬।","roman":"Adooraa zimardee bar aavurad dood | 6 |","meaning_en":"","page":2615}]},{"type":"verse","number":[7],"number_text":"੭।","page":2617,"lines":[{"gurmukhi":"ਵਜ਼ੀਰ ਯਕੇ ਬੂਦ ਓ ਹੋਸ਼ਮੰਦ।","roman":"Vazeer yake bood o hoshmand |","meaning_en":"","page":2617},{"gurmukhi":"ਰਈਯਤ ਨਿਵਾਜ਼ ਅਸਤ ਦੁਸ਼ਮਨ ਗਜ਼ੰਦ। ੭।","roman":"Raeeyat nivaaz asat dushman gazand | 7 |","meaning_en":"","page":2617}]},{"type":"verse","number":[8],"number_text":"੮।","page":2617,"lines":[{"gurmukhi":"ਵਜ਼ਾਂ ਦੁਖ਼ਤਰੇ ਹਸਤ ਰੌਸ਼ਨ ਚਰਾਗ।","roman":"Vazaan dukhatre hasat raushan charaag |","meaning_en":"","page":2617},{"gurmukhi":"ਕਿ ਨਾਮੇ ਅਜ਼ਾਂ ਬੂਦ ਰੌਸ਼ਨ ਦਿਮਾਗ। ੮।","roman":"Ki naame azaan bood raushan dimaag | 8 |","meaning_en":"","page":2617}]},{"type":"verse","number":[9],"number_text":"੯।","page":2617,"lines":[{"gurmukhi":"ਬ ਮਕਤਬ ਸਪੁਰਦੰਦ ਹਰ ਦੋ ਤਿਫ਼ਲ।","roman":"Ba maktab sapurdand har do tifal |","meaning_en":"","page":2617},{"gurmukhi":"ਕਿ ਤਿਫ਼ਲਸ਼ ਬਸੇ ਰੋਜ਼ ਗਸ਼ਤੰਦ ਖ਼ਿਜ਼ਲ। ੯।","roman":"Ki tiflash base roz gashtand khizal | 9 |","meaning_en":"","page":2617}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2617,"lines":[{"gurmukhi":"ਨਿਸ਼ਸਤੰਦ ਦਾਨਾਇ ਮੌਲਾਇ ਰੂਮ।","roman":"Nishastand daanaai maulaai room |","meaning_en":"","page":2617},{"gurmukhi":"ਕਿ ਦਿਰਮਸ਼ ਬਬਖ਼ਸ਼ੀਦ ਆਂ ਮਰਜ਼ ਬੂਮ। ੧੦।","roman":"Ki dirmash babakhsheed aan maraz boom | 10 |","meaning_en":"","page":2617}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":2617,"lines":[{"gurmukhi":"ਨਿਸ਼ਸਤੰਦ ਦਰ ਆਂ ਜਾਇ ਤਿਫ਼ਲੇ ਬਸੇ।","roman":"Nishastand dar aan jaai tifle base |","meaning_en":"","page":2617},{"gurmukhi":"ਬੁਖ਼ਾਂਦੇ ਸੁਖ਼ਨ ਅਜ਼ ਕਿਤਾਬ ਹਰ ਕਸੇ। ੧੧।","roman":"Bukhaande sukhan az kitaab har kase | 11 |","meaning_en":"","page":2617}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":2617,"lines":[{"gurmukhi":"ਬ ਬਗਲ ਅੰਦਰ ਆਰੰਦ ਹਰ ਯਕ ਕਿਤਾਬ।","roman":"Ba bagal andar aarand har yak kitaab |","meaning_en":"","page":2617},{"gurmukhi":"ਜ਼ਿ ਤਉਰੇਤ ਅੰਜੀਲ ਵਜਹੇ ਅਦਾਬ। ੧੨।","roman":"Zi tauret anjeel vajhe adaab | 12 |","meaning_en":"","page":2617}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":2617,"lines":[{"gurmukhi":"ਦੁ ਮਕਤਬ ਕੁਨਾਨੀਦ ਹਫ਼ਤ ਅਜ਼ ਜ਼ੁਬਾਂ।","roman":"Du maktab kunaaneed hafat az zubaan |","meaning_en":"","page":2617},{"gurmukhi":"ਯਕੇ ਮਰਦ ਬੁਖ਼ਾਂਦੰਦ ਦੀਗਰ ਜ਼ਨਾਂ। ੧੩।","roman":"Yake marad bukhaandand deegar zanaan | 13 |","meaning_en":"","page":2617}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2617,"lines":[{"gurmukhi":"ਕਿ ਤਿਫ਼ਲਾ ਬੁਖ਼ਾਦੰਦ ਮੁਲਾਂ ਖ਼ੁਸ਼ਸ਼।","roman":"Ki tiflaa bukhaadand mulaan khushash |","meaning_en":"","page":2617},{"gurmukhi":"ਜ਼ਨਾਰਾ ਬੁਖ਼ਾਂਦੰਦ ਜ਼ਨੇ ਫ਼ਾਜ਼ਲਸ਼। ੧੪।","roman":"Zanaaraa bukhaandand zane faazlash | 14 |","meaning_en":"","page":2617}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":2617,"lines":[{"gurmukhi":"ਵਜ਼ਾਂ ਦਰਮਿਯਾਂ ਬੂਦ ਦੀਵਾਰ ਜ਼ੀਂ।","roman":"Vazaan darmiyaan bood deevaar zeen |","meaning_en":"","page":2617},{"gurmukhi":"ਯਕੇ ਆਂ ਤਰਫ਼ ਬੂਦ ਯਕੇ ਤਰਫ਼ ਈਂ। ੧੫।","roman":"Yake aan taraf bood yake taraf een | 15 |","meaning_en":"","page":2617}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":2617,"lines":[{"gurmukhi":"ਸਬਕ ਬੁਰਦ ਹਰ ਦੋ ਜ਼ਿ ਹਰ ਯਕ ਹੁਨਰ।","roman":"Sabak burad har do zi har yak hunar |","meaning_en":"","page":2617},{"gurmukhi":"ਇਲਮ ਕਸ਼ਮਕਸ਼ ਕਰਦ ਬਾ ਯਕ ਦਿਗਰ। ੧੬।","roman":"Ilam kashamkash karad baa yak digar | 16 |","meaning_en":"","page":2617}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":2617,"lines":[{"gurmukhi":"ਸੁਖ਼ਨ ਹਰ ਯਕੇ ਰਾਂਦ ਹਰ ਯਕ ਕਿਤਾਬ।","roman":"Sukhan har yake raand har yak kitaab |","meaning_en":"","page":2617},{"gurmukhi":"ਜ਼ੁਬਾਂ ਫ਼ਰਸ਼ ਅਰਬੀ ਬਿਗੋਯਦ ਜਵਾਬ। ੧੭।","roman":"Zubaan farash arbee bigoyad javaab | 17 |","meaning_en":"","page":2617}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":2617,"lines":[{"gurmukhi":"ਇਲਮ ਰਾ ਸੁਖਨ ਰਾਂਦ ਬਾ ਯਕ ਦਿਗਰ।","roman":"Ilam raa sukhan raand baa yak digar |","meaning_en":"","page":2617},{"gurmukhi":"ਜ਼ਿ ਕਾਮਲ ਜ਼ਿ ਜ਼ਾਯਲ ਜ਼ਿ ਨਾਰਦ ਸਿਯਰ। ੧੮।","roman":"Zi kaamal zi zaayal zi naarad siyar | 18 |","meaning_en":"","page":2617}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":2617,"lines":[{"gurmukhi":"ਕਿ ਸ਼ਮਸ਼ੇਰ ਇਲਮੋ ਅਲਮਬਰ ਕਸ਼ੀਦ।","roman":"Ki shamsher ilmo alambar kasheed |","meaning_en":"","page":2617},{"gurmukhi":"ਬਹਾਰੇ ਜਵਾਨੀ ਬ ਹਰਦੋ ਰਸ਼ੀਦ। ੧੯।","roman":"Bahaare javaanee ba hardo rasheed | 19 |","meaning_en":"","page":2617}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2617,"lines":[{"gurmukhi":"ਬਹਾਰਸ਼ ਦਰ ਆਮਦ ਗੁਲੇ ਦੋਸਤਾਂ।","roman":"Bahaarash dar aamad gule dostaan |","meaning_en":"","page":2617},{"gurmukhi":"ਬਜੁੰਬਸ਼ ਦਰਾਮਦ ਸਹੇ ਚੀਸਤਾਂ। ੨੦।","roman":"Bajunbash daraamad sahe cheestaan | 20 |","meaning_en":"","page":2617}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":2617,"lines":[{"gurmukhi":"ਬਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਸ਼ਹਿਨਸ਼ਾਹਿ ਚੀਂ।","roman":"Barkhash andar aamad shahinshaahi cheen |","meaning_en":"","page":2617},{"gurmukhi":"ਬਖ਼ੂਬੀ ਦਰਾਮਦ ਤਨੇ ਨਾਜ਼ਨੀਂ ੨੧।","roman":"Bakhoobee daraamad tane naazneen 21 |","meaning_en":"","page":2617}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2617,"lines":[{"gurmukhi":"ਬ ਖ਼ੂਬੀ ਦਰ ਆਮਦ ਗੁਲੇ ਬੋਸਤਾਂ।","roman":"Ba khoobee dar aamad gule bostaan |","meaning_en":"","page":2617},{"gurmukhi":"ਬ ਐਸ਼ ਅੰਦਰ ਆਮਦ ਦਿਲੇ ਦੋਸਤਾਂ। ੨੨।","roman":"Ba aish andar aamad dile dostaan | 22 |","meaning_en":"","page":2617}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2619,"lines":[{"gurmukhi":"ਜ਼ਿ ਦੇਵਾਰ ਜੋ ਅੰਦਰੂੰ ਮੂਸ ਹਸਤ।","roman":"Zi devaar jo androon moos hasat |","meaning_en":"","page":2619},{"gurmukhi":"ਜ਼ਿ ਦੇਵਾਰ ਓ ਹਮ ਚੂੰ ਸੂਰਾਖ ਗਸ਼ਤ। ੨੩।","roman":"Zi devaar o ham choon sooraakh gashat | 23 |","meaning_en":"","page":2619}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2619,"lines":[{"gurmukhi":"ਬ ਦੀਦਨ ਅਜ਼ਾਂ ਅੰਦਰੂੰ ਹਰ ਦੁ ਤਨ।","roman":"Ba deedan azaan androon har du tan |","meaning_en":"","page":2619},{"gurmukhi":"ਚਰਾਗੇ ਜਹਾਂ ਆਫ਼ਤਾਬੇ ਯਮਨ। ੨੪।","roman":"Charaage jahaan aaftaabe yaman | 24 |","meaning_en":"","page":2619}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":2619,"lines":[{"gurmukhi":"ਚੁਨਾ ਇਸ਼ਕ ਆਵੇਖ਼ਤ ਹਰ ਦੋ ਨਿਹਾਂ।","roman":"Chunaa ishak aavekhat har do nihaan |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਇਲਮਸ਼ ਰਵਦ ਦਸਤ ਹੋਸ਼ ਅਜ਼ ਜਹਾਂ। ੨੫।","roman":"Ki ilmash ravad dasat hosh az jahaan | 25 |","meaning_en":"","page":2619}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2619,"lines":[{"gurmukhi":"ਚੁਨਾ ਹਰ ਦੁ ਆਵੇਖ਼ਤ ਬਾਹਮ ਰਗੇਬ।","roman":"Chunaa har du aavekhat baaham rageb |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਦਸਤ ਅਜ਼ ਇਨਾਰਫ਼ਤ ਪਾ ਅਜ਼ ਰਕੇਬ। ੨੬।","roman":"Ki dasat az inaarfat paa az rakeb | 26 |","meaning_en":"","page":2619}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2619,"lines":[{"gurmukhi":"ਬ ਪੁਰਸ਼ੀਦ ਹਰ ਦੋ ਕਿ ਏ ਨੇਕ ਖ਼ੋਇ।","roman":"Ba pursheed har do ki e nek khoi |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਏ ਆਫ਼ਤਾਬੇ ਜਹਾਂ ਮਾਹ ਰੋਇ। ੨੭।","roman":"Ki e aaftaabe jahaan maah roi | 27 |","meaning_en":"","page":2619}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":2619,"lines":[{"gurmukhi":"ਕਿ ਈਂ ਹਾਲ ਗੁਜ਼ਰਦ ਬ ਆਂ ਹਰ ਦੋ ਤਨ।","roman":"Ki een haal guzrad ba aan har do tan |","meaning_en":"","page":2619},{"gurmukhi":"ਬਿ ਪੁਰਸ਼ੀਦ ਅਖ਼ਵੰਦ ਵ ਅਖ਼ਵੰਦ ਜ਼ਨ। ੨੮।","roman":"Bi pursheed akhvand va akhvand zan | 28 |","meaning_en":"","page":2619}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2619,"lines":[{"gurmukhi":"ਚਰਾਗੇ ਫ਼ਲਕ ਆਫ਼ਤਾਬੇ ਜਹਾਂ।","roman":"Charaage falak aaftaabe jahaan |","meaning_en":"","page":2619},{"gurmukhi":"ਚਰਾ ਲਾਗਰੀ ਗਸ਼ਤ ਵਜਹੇ ਨੁਮਾਂ। ੨੯।","roman":"Charaa laagree gashat vajhe numaan | 29 |","meaning_en":"","page":2619}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2619,"lines":[{"gurmukhi":"ਚਿ ਆਜ਼ਾਰ ਗਸ਼ਤਹ ਬੁਗੋ ਜਾਨ ਮਾ।","roman":"Chi aazaar gashtah bugo jaan maa |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਲਾਗਰ ਚਰਾ ਗਸ਼ਤੀ ਏ ਜਾਨ ਮਾ। ੩੦।","roman":"Ki laagar charaa gashtee e jaan maa | 30 |","meaning_en":"","page":2619}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2619,"lines":[{"gurmukhi":"ਅਜ਼ਾਰਸ਼ ਬੁਗੋ ਤਾ ਇਲਾਜੇ ਕੁਨਮ।","roman":"Azaarash bugo taa ilaaje kunam |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਮਰਜ਼ੇ ਸ਼ੁਮਾ ਰਾ ਖ਼ਿਰਾਜ਼ੇ ਕੁਨਮ। ੩੧।","roman":"Ki marze shumaa raa khiraaze kunam | 31 |","meaning_en":"","page":2619}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2619,"lines":[{"gurmukhi":"ਸ਼ੁਨੀਦ ਈਂ ਸੁਖ਼ਨ ਰਾ ਨ ਦਾਦਸ਼ ਜਵਾਬ।","roman":"Shuneed een sukhan raa na daadash javaab |","meaning_en":"","page":2619},{"gurmukhi":"ਫ਼ਰੋ ਬੁਰਦ ਹਰ ਦੋ ਤਨੇ ਇਸ਼ਕ ਤਾਬ। ੩੨।","roman":"Faro burad har do tane ishak taab | 32 |","meaning_en":"","page":2619}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2619,"lines":[{"gurmukhi":"ਚੁ ਗੁਜ਼ਰੀਦ ਬਰਵੈ ਦੁ ਸੇ ਚਾਰ ਰੋਜ਼।","roman":"Chu guzreed barvai du se chaar roz |","meaning_en":"","page":2619},{"gurmukhi":"ਬਰਾਮਦ ਦੁ ਤਨ ਹਰ ਦੋ ਗੇਤੀ ਫ਼ਰੋਜ਼। ੩੩।","roman":"Baraamad du tan har do getee faroz | 33 |","meaning_en":"","page":2619}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2619,"lines":[{"gurmukhi":"ਬਰੋ ਦੂਰ ਗਸ਼ਤੰਦ ਤਿਫ਼ਲੀ ਗੁਬਾਰ।","roman":"Baro door gashtand tiflee gubaar |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਮੁਹਰਸ਼ ਬਰ ਆਵੁਰਦ ਚੂੰ ਨੌਬਹਾਰ। ੩੪।","roman":"Ki muhrash bar aavurad choon naubhaar | 34 |","meaning_en":"","page":2619}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2619,"lines":[{"gurmukhi":"ਵਜ਼ਾਂ ਫ਼ਾਜ਼ਲਸ਼ ਬੂਦ ਦੁਖ਼ਤਰ ਯਕੇ।","roman":"Vazaan faazlash bood dukhtar yake |","meaning_en":"","page":2619},{"gurmukhi":"ਕਿ ਸੂਰਤ ਜਮਾਲ ਅਸਤ ਦਾਨਸ਼ ਬਸ਼ੇ। ੩੫।","roman":"Ki soorat jamaal asat daanash bashe | 35 |","meaning_en":"","page":2619}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":2619,"lines":[{"gurmukhi":"ਸ਼ਨਾਸੀਦ ਓ ਰਾ ਜ਼ਿ ਹਾਲਤ ਵਜ਼ਾਂ।","roman":"Shanaaseed o raa zi haalat vazaan |","meaning_en":"","page":2619},{"gurmukhi":"ਬਗੁਫ਼ਤਸ਼ ਦਰੂੰ ਖ਼ਿਲਵਤਸ਼ ਖ਼ੁਸ਼ ਜ਼ੁਬਾਂ। ੩੬।","roman":"Baguftash daroon khilavtash khush zubaan | 36 |","meaning_en":"","page":2619}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":2619,"lines":[{"gurmukhi":"ਕਿ ਏ ਸਰਵ ਕਦ ਮਾਹ ਰੋ ਸੀਮ ਤਨ।","roman":"Ki e sarav kad maah ro seem tan |","meaning_en":"","page":2619},{"gurmukhi":"ਚਰਾਗੇ ਫ਼ਲਕ ਆਫ਼ਤਾਬੇ ਯਮਨ। ੩੭।","roman":"Charaage falak aaftaabe yaman | 37 |","meaning_en":"","page":2619}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2619,"lines":[{"gurmukhi":"ਜੁਦਾਈ ਮਰਾ ਅਜ਼ ਤੁਰਾ ਕਤਰਹ ਨੇਸਤ।","roman":"Judaaee maraa az turaa katrah nesat |","meaning_en":"","page":2619},{"gurmukhi":"ਬ ਦੀਦਨ ਦੁ ਕਾਲਬ ਬ ਗੁਫ਼ਤਮ ਯਕੇਸਤ। ੩੮।","roman":"Ba deedan du kaalab ba guftam yakesat | 38 |","meaning_en":"","page":2619}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2621,"lines":[{"gurmukhi":"ਬ ਮਨ ਹਾਲ ਗੋ ਤਾ ਚਿ ਗੁਜ਼ਰਦ ਤੁਰਾ।","roman":"Ba man haal go taa chi guzrad turaa |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਸੋਜ਼ਦ ਹਮਹ ਜਾਨ ਜਿਗਰੇ ਮਰਾ। ੩੯।","roman":"Ki sozad hamah jaan jigre maraa | 39 |","meaning_en":"","page":2621}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2621,"lines":[{"gurmukhi":"ਕਿ ਪਿਨਹਾਂ ਸੁਖ਼ਨ ਕਰਦ ਯਾਰਾਂ ਖ਼ਤਾਸਤ।","roman":"Ki pinhaan sukhan karad yaaraan khataasat |","meaning_en":"","page":2621},{"gurmukhi":"ਅਗਰ ਰਾਸ ਗੋਈ ਤੁ ਬਰ ਮਨ ਰਵਾਸਤ। ੪੦।","roman":"Agar raas goee tu bar man ravaasat | 40 |","meaning_en":"","page":2621}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2621,"lines":[{"gurmukhi":"ਕਿ ਦੀਗਰ ਬਗੋਯਮ ਮਰਾ ਰਾਸਤ ਗੋ।","roman":"Ki deegar bagoyam maraa raasat go |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਅਜ਼ ਖ਼ੂਨ ਜਿਗਰੇ ਮਰਾ ਤੋ ਬਿਸ਼ੋ। ੪੧।","roman":"Ki az khoon jigre maraa to bisho | 41 |","meaning_en":"","page":2621}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":2621,"lines":[{"gurmukhi":"ਸੁਖ਼ਨ ਦੁਜ਼ਦਗੀ ਕਰਦ ਯਾਰਾਂ ਖ਼ਤਾਸਤ।","roman":"Sukhan duzadgee karad yaaraan khataasat |","meaning_en":"","page":2621},{"gurmukhi":"ਅਮੀਰਾਨ ਦੁਜ਼ਦੀ ਵਜ਼ੀਰਾਂ ਖ਼ਤਾਸਤ। ੪੨।","roman":"Ameeraan duzdee vazeeraan khataasat | 42 |","meaning_en":"","page":2621}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":2621,"lines":[{"gurmukhi":"ਸੁਖ਼ਨ ਗੁਫ਼ਤਨੇ ਰਾਸਤ ਗੁਫ਼ਤਨ ਖ਼ੁਸ਼ ਅਸਤ।","roman":"Sukhan gufatne raasat guftan khush asat |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਹਕ ਗੁਫ਼ਤਨੋ ਹਮ ਚੁ ਸਾਫ਼ੀ ਦਿਲ ਅਸਤ। ੪੩।","roman":"Ki hak gufatno ham chu saafee dil asat | 43 |","meaning_en":"","page":2621}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2621,"lines":[{"gurmukhi":"ਬਸੇ ਬਾਰ ਗੁਫ਼ਤਸ਼ ਜਵਾਬੋ ਨ ਦਾਦ।","roman":"Base baar guftash javaabo na daad |","meaning_en":"","page":2621},{"gurmukhi":"ਜਵਾਬੇ ਜ਼ੁਬਾਂ ਸੁਖ਼ਨ ਸ਼ੀਰੀ ਕੁਸ਼ਾਦ। ੪੪।","roman":"Javaabe zubaan sukhan sheeree kushaad | 44 |","meaning_en":"","page":2621}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":2621,"lines":[{"gurmukhi":"ਯਕੇ ਮਜਲਿਸ ਆਰਾਸਤ ਬਾ ਰੋਦ ਜਾਮ।","roman":"Yake majlis aaraasat baa rod jaam |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਹਮ ਮਸਤ ਸ਼ੁਦ ਮਜਲਸੇ ਓ ਤਮਾਮ। ੪੫।","roman":"Ki ham masat shud majalse o tamaam | 45 |","meaning_en":"","page":2621}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":2621,"lines":[{"gurmukhi":"ਬ ਕੈਫ਼ਸ਼ ਹਮਹ ਹਮ ਚੁ ਆਵੇਖ਼ਤੰਦ।","roman":"Ba kaifash hamah ham chu aavekhtand |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਜ਼ਖ਼ਮੇ ਜਿਗਰ ਬਾਜ਼ੁਬਾਂ ਰੇਖ਼ਤੰਦ। ੪੬।","roman":"Ki zakhme jigar baazubaan rekhtand | 46 |","meaning_en":"","page":2621}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2621,"lines":[{"gurmukhi":"ਸੁਖ਼ਨ ਬਾ ਜ਼ੁਬਾਂ ਹਮ ਚੁ ਗੋਯਦ ਮੁਦਾਮ।","roman":"Sukhan baa zubaan ham chu goyad mudaam |","meaning_en":"","page":2621},{"gurmukhi":"ਨ ਗੋਯਦ ਬਜੁਜ਼ ਸੁਖ਼ਨ ਮਹਬੂਬ ਨਾਮ। ੪੭।","roman":"Na goyad bajuz sukhan mahboob naam | 47 |","meaning_en":"","page":2621}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":2621,"lines":[{"gurmukhi":"ਦਿਗਰ ਮਜਲਿਸ ਆਰਾਸਤ ਬਾ ਰੋਦ ਚੰਗ।","roman":"Digar majlis aaraasat baa rod chang |","meaning_en":"","page":2621},{"gurmukhi":"ਜਵਾਨਾਨ ਸ਼ਾਇਸਤਹੇ ਖ਼ੂਬ ਰੰਗ। ੪੮।","roman":"Javaanaan shaaisathe khoob rang | 48 |","meaning_en":"","page":2621}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":2621,"lines":[{"gurmukhi":"ਹਮਹ ਮਸਤ ਖ਼ੋ ਸ਼ੁਦ ਹਮਹ ਖ਼ੂਬ ਮਸਤ।","roman":"Hamah masat kho shud hamah khoob masat |","meaning_en":"","page":2621},{"gurmukhi":"ਇਨਾਨੇ ਫ਼ਜ਼ੀਲਤ ਬਰੂੰ ਸ਼ੁਦ ਜ਼ਿ ਦਸਤ। ੪੯।","roman":"Inaane fazeelat baroon shud zi dasat | 49 |","meaning_en":"","page":2621}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2621,"lines":[{"gurmukhi":"ਹਰਾ ਕਸ ਕਿ ਅਜ਼ ਇਲਮ ਸੁਖ਼ਨਸ਼ ਬਿਰਾਂਦ।","roman":"Haraa kas ki az ilam sukhnash biraand |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਅਜ਼ ਬੇਖ਼ੁਦੀ ਨਾਮ ਹਰਦੋ ਬੁਖਾਂਦ। ੫੦।","roman":"Ki az bekhudee naam hardo bukhaand | 50 |","meaning_en":"","page":2621}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2621,"lines":[{"gurmukhi":"ਚੁ ਇਲਮੋ ਫ਼ਜ਼ੀਲਤ ਫਰਾਮੋਸ਼ ਗਸ਼ਤ।","roman":"Chu ilmo fazeelat pharaamosh gashat |","meaning_en":"","page":2621},{"gurmukhi":"ਬੁਖ਼ਾਦੰਦ ਬਾ ਯਕ ਦਿਗਰ ਨਾਮ ਮਸਤ। ੫੧।","roman":"Bukhaadand baa yak digar naam masat | 51 |","meaning_en":"","page":2621}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2621,"lines":[{"gurmukhi":"ਹਰਾਂ ਕਸ ਕਿ ਦੇਰੀਨਹ ਰਾ ਹਸਤ ਦੋਸਤ।","roman":"Haraan kas ki dereenah raa hasat dosat |","meaning_en":"","page":2621},{"gurmukhi":"ਜ਼ੁਬਾਂ ਖ਼ੁਦ ਕੁਸ਼ਾਯਿੰਦਹ ਅਜ਼ ਨਾਮ ਓਸਤ। ੫੨।","roman":"Zubaan khud kushaayindah az naam osat | 52 |","meaning_en":"","page":2621}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":2621,"lines":[{"gurmukhi":"ਸ਼ਨਾਸ਼ਿਦ ਕਿ ਈਂ ਗੁਲ ਸੁਖ਼ਨ ਆਸ਼ਕ ਅਸਤ।","roman":"Shanaashid ki een gul sukhan aashak asat |","meaning_en":"","page":2621},{"gurmukhi":"ਬ ਗੁਫ਼ਤਨ ਹੁਮਾਯੂੰ ਸੁਬਕ ਤਨ ਖ਼ੁਸ਼ ਅਸਤ। ੫੩।","roman":"Ba guftan humaayoon subak tan khush asat | 53 |","meaning_en":"","page":2621}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":2621,"lines":[{"gurmukhi":"ਕਿ ਅਜ਼ ਇਸ਼ਕ ਵ ਅਜ਼ ਮੁਸ਼ਕ ਅਜ਼ ਖ਼ਮਰ ਖ਼ੂੰ।","roman":"Ki az ishak va az mushak az khamar khoon |","meaning_en":"","page":2621},{"gurmukhi":"ਕਿ ਪਿਨਹਾਂ ਨ ਮਾਂਦ ਅਸਤ ਆਮਦ ਬਰੂੰ। ੫੪।","roman":"Ki pinhaan na maand asat aamad baroon | 54 |","meaning_en":"","page":2621}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":2623,"lines":[{"gurmukhi":"ਬ ਸ਼ਹਰ ਅੰਦਰੂੰ ਗਸ਼ਤ ਸ਼ੁਹਰਤ ਪਜ਼ੀਰ।","roman":"Ba shahar androon gashat shuhrat pazeer |","meaning_en":"","page":2623},{"gurmukhi":"ਕਿ ਆਜ਼ਾਦਹੇ ਸ਼ਾਹੁ ਵ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ। ੫੫।","roman":"Ki aazaadhe shaahu va dukhtar vazeer | 55 |","meaning_en":"","page":2623}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2623,"lines":[{"gurmukhi":"ਸ਼ੁਨੀਦ ਈਂ ਸੁਖ਼ਨ ਸ਼ਹਿ ਦੁ ਕਿਸ਼ਤੀ ਬੁਖਾਂਦ।","roman":"Shuneed een sukhan shahi du kishtee bukhaand |","meaning_en":"","page":2623},{"gurmukhi":"ਜੁਦਾ ਬਰ ਜੁਦਾ ਹਰ ਦੁ ਕਿਸ਼ਤੀ ਨਿਸ਼ਾਂਦ। ੫੬।","roman":"Judaa bar judaa har du kishtee nishaand | 56 |","meaning_en":"","page":2623}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2623,"lines":[{"gurmukhi":"ਰਵਾਂ ਕਰਦ ਓ ਰਾ ਬ ਦਰੀਯਾ ਅਜ਼ੀਮ।","roman":"Ravaan karad o raa ba dareeyaa azeem |","meaning_en":"","page":2623},{"gurmukhi":"ਦੁ ਕਿਸ਼ਤੀ ਯਕੇ ਸ਼ੁਦ ਹਮਹ ਮੌਜ ਬੀਮ। ੫੭।","roman":"Du kishtee yake shud hamah mauj beem | 57 |","meaning_en":"","page":2623}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":2623,"lines":[{"gurmukhi":"ਦੁ ਕਿਸ਼ਤੀ ਯਕੇ ਗਸ਼ਤ ਬ ਹੁਕਮੇ ਅਲਾਹ।","roman":"Du kishtee yake gashat ba hukme alaah |","meaning_en":"","page":2623},{"gurmukhi":"ਬ ਯਕ ਜਾ ਦਰਾਮਦ ਹੁਮਾ ਸ਼ਮਸ਼ ਮਾਹ। ੫੮।","roman":"Ba yak jaa daraamad humaa shamash maah | 58 |","meaning_en":"","page":2623}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":2623,"lines":[{"gurmukhi":"ਬੁਬੀਂ ਕੁਦਰਤੇ ਕਿਰਦਗਾਰੇ ਅਲਾਹ।","roman":"Bubeen kudarte kiradgaare alaah |","meaning_en":"","page":2623},{"gurmukhi":"ਦੁ ਤਨ ਰਾ ਯਕੇ ਕਰਦ ਅਜ਼ ਹੁਕਮ ਸ਼ਾਹਿ। ੫੯।","roman":"Du tan raa yake karad az hukam shaahi | 59 |","meaning_en":"","page":2623}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":2623,"lines":[{"gurmukhi":"ਦੁ ਕਿਸ਼ਤੀ ਦਰਾਮਦ ਬ ਯਕ ਜਾ ਦੁ ਤਨ।","roman":"Du kishtee daraamad ba yak jaa du tan |","meaning_en":"","page":2623},{"gurmukhi":"ਚਰਾਗੇ ਜਹਾਂ ਆਫ਼ਤਾਬੇ ਯਮਨ। ੬੦।","roman":"Charaage jahaan aaftaabe yaman | 60 |","meaning_en":"","page":2623}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":2623,"lines":[{"gurmukhi":"ਬਿ ਰਫ਼ਤੰਦ ਕਿਸ਼ਤੀ ਬ ਦਰੀਯਾਇ ਗਾਰ।","roman":"Bi raftand kishtee ba dareeyaai gaar |","meaning_en":"","page":2623},{"gurmukhi":"ਬ ਮੌਜ ਅੰਦਰ ਆਮਦ ਚੁ ਬਰਗੇ ਬਹਾਰ। ੬੧।","roman":"Ba mauj andar aamad chu barge bahaar | 61 |","meaning_en":"","page":2623}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2623,"lines":[{"gurmukhi":"ਯਕੇ ਅਜ਼ਦਹਾ ਬੂਦ ਆਂ ਜਾ ਨਿਸ਼ਸਤ।","roman":"Yake azadhaa bood aan jaa nishsat |","meaning_en":"","page":2623},{"gurmukhi":"ਬ ਖ਼ੁਰਦਨ ਦਰਾਮਦ ਵਜ਼ਾਂ ਕਰਦ ਜਸਤ। ੬੨।","roman":"Ba khurdan daraamad vazaan karad jasat | 62 |","meaning_en":"","page":2623}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2623,"lines":[{"gurmukhi":"ਦਿਗਰ ਪੇਸ਼ ਤਰ ਬੂਦ ਕਹਰੇ ਬਲਾ।","roman":"Digar pesh tar bood kahre balaa |","meaning_en":"","page":2623},{"gurmukhi":"ਦੁ ਦਸਤਸ਼ ਸਤੂੰ ਕਰਦ ਬੇ ਸਰ ਨੁਮਾ। ੬੩।","roman":"Du dastash satoon karad be sar numaa | 63 |","meaning_en":"","page":2623}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":2623,"lines":[{"gurmukhi":"ਮਿਯਾਂ ਰਫ਼ਤ ਸ਼ੁਦ ਕਿਸ਼ਤੀਏ ਹਰ ਦੁ ਦਸਤ।","roman":"Miyaan rafat shud kishtee'e har du dasat |","meaning_en":"","page":2623},{"gurmukhi":"ਬਨੇਸੇ ਦਮਾਨਦ ਅਜ਼ੋ ਮਾਰ ਮਸਤ। ੬੪।","roman":"Banese damaanad azo maar masat | 64 |","meaning_en":"","page":2623}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2623,"lines":[{"gurmukhi":"ਗਰਿਫ਼ਤੰਦ ਓ ਰਾ ਬਦਸਤ ਅੰਦਰੂੰ।","roman":"Gariftand o raa badsat androon |","meaning_en":"","page":2623},{"gurmukhi":"ਬ ਬਖ਼ਸ਼ੀਦ ਓ ਰਾ ਨ ਖ਼ੁਰਦੰਦ ਖ਼ੂੰ। ੬੫।","roman":"Ba bakhsheed o raa na khurdand khoon | 65 |","meaning_en":"","page":2623}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2623,"lines":[{"gurmukhi":"ਚੁਨਾ ਜੰਗ ਸ਼ੁਦ ਅਜ਼ਦਹਾ ਬਾ ਬਲਾ।","roman":"Chunaa jang shud azadhaa baa balaa |","meaning_en":"","page":2623},{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਨਿਆਮਦ ਬ ਹੁਕਮੇ ਖ਼ੁਦਾ। ੬੬।","roman":"Ki beroon niaamad ba hukme khudaa | 66 |","meaning_en":"","page":2623}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2623,"lines":[{"gurmukhi":"ਚੁਨਾ ਮੌਜ ਖ਼ੇਜ਼ਦ ਜਿ ਦਰੀਯਾ ਅਜ਼ੀਮ।","roman":"Chunaa mauj khezad ji dareeyaa azeem |","meaning_en":"","page":2623},{"gurmukhi":"ਕਿ ਦੀਗਰ ਨ ਦਾਨਿਸਤ ਜੁਜ਼ ਯਕ ਕਰੀਮ। ੬੭।","roman":"Ki deegar na daanisat juz yak kareem | 67 |","meaning_en":"","page":2623}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2623,"lines":[{"gurmukhi":"ਰਵਾਂ ਗਸ਼ਤ ਕਿਸ਼ਤੀ ਬ ਮੌਜੇ ਬਲਾ।","roman":"Ravaan gashat kishtee ba mauje balaa |","meaning_en":"","page":2623},{"gurmukhi":"ਬਰਾਹੇ ਖ਼ਲਾਸੀ ਜ਼ਿ ਰਹਮਤ ਖ਼ੁਦਾ। ੬੮।","roman":"Baraahe khalaasee zi rahmat khudaa | 68 |","meaning_en":"","page":2623}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2623,"lines":[{"gurmukhi":"ਬ ਆਖ਼ਰ ਹਮ ਅਜ਼ ਹੁਕਮ ਪਰਵਰਦਿਗਾਰ।","roman":"Ba aakhar ham az hukam parvardigaar |","meaning_en":"","page":2623},{"gurmukhi":"ਕਿ ਕਿਸ਼ਤੀ ਬਰ ਆਮਦ ਜ਼ਿ ਦਰੀਯਾ ਕਿਨਾਰ। ੬੯।","roman":"Ki kishtee bar aamad zi dareeyaa kinaar | 69 |","meaning_en":"","page":2623}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2623,"lines":[{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਬਰਾਮਦ ਅਜ਼ਾਂ ਹਰ ਦੁ ਤਨ।","roman":"Ki beroon baraamad azaan har du tan |","meaning_en":"","page":2623},{"gurmukhi":"ਨਿਸ਼ਸਤਹ ਲਬੇ ਆਬ ਦਰੀਯਾ ਯਮਨ। ੭੦।","roman":"Nishastah labe aab dareeyaa yaman | 70 |","meaning_en":"","page":2623}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2625,"lines":[{"gurmukhi":"ਬਰਾਮਦ ਯਕੇ ਸ਼ੇਰ ਦੀਦਨ ਸ਼ਿਤਾਬ।","roman":"Baraamad yake sher deedan shitaab |","meaning_en":"","page":2625},{"gurmukhi":"ਬ ਖ਼ੁਰਦਨ ਅਜ਼ਾਂ ਹਰ ਦੁ ਤਨ ਰਾ ਕਬਾਬ। ੭੧।","roman":"Ba khurdan azaan har du tan raa kabaab | 71 |","meaning_en":"","page":2625}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2625,"lines":[{"gurmukhi":"ਜ਼ਿ ਦਰੀਯਾ ਬਰ ਆਮਦ ਜ਼ਿ ਮਗਰੇ ਅਜ਼ੀਮ।","roman":"Zi dareeyaa bar aamad zi magre azeem |","meaning_en":"","page":2625},{"gurmukhi":"ਖ਼ੁਰਮ ਹਰ ਦੁ ਤਨ ਰਾ ਬ ਹੁਕਮੇ ਕਰੀਮ। ੭੨।","roman":"Khuram har du tan raa ba hukme kareem | 72 |","meaning_en":"","page":2625}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2625,"lines":[{"gurmukhi":"ਬਜਾਇਸ਼ ਦਰਾਮਦ ਜ਼ਿ ਸ਼ੇਰੇ ਸ਼ਿਤਾਬ।","roman":"Bajaaish daraamad zi shere shitaab |","meaning_en":"","page":2625},{"gurmukhi":"ਗਜ਼ੰਦਸ਼ ਹਮੀ ਬੁਰਦ ਬਰ ਰੋਦ ਆਬ। ੭੩।","roman":"Gazandash hamee burad bar rod aab | 73 |","meaning_en":"","page":2625}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":2625,"lines":[{"gurmukhi":"ਬ ਪੇਚੀਦ ਸਰ ਓ ਖ਼ਤਾ ਗਸ਼ਤ ਸ਼ੇਰ।","roman":"Ba pecheed sar o khataa gashat sher |","meaning_en":"","page":2625},{"gurmukhi":"ਬ ਦਹਨੇ ਦਿਗਰ ਦੁਸ਼ਮਨ ਅਫ਼ਤਦ ਦਲੇਰ। ੭੪।","roman":"Ba dahne digar dushman aftad daler | 74 |","meaning_en":"","page":2625}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2625,"lines":[{"gurmukhi":"ਬ ਗੀਰਦ ਮਗਰ ਦਸਤ ਸ਼ੇਰੋ ਸ਼ਿਤਾਬ।","roman":"Ba geerad magar dasat shero shitaab |","meaning_en":"","page":2625},{"gurmukhi":"ਬ ਬੁਰਦੰਦ ਓ ਰਾ ਕਸ਼ੀਦਹ ਦਰ ਆਬ। ੭੫।","roman":"Ba burdand o raa kasheedah dar aab | 75 |","meaning_en":"","page":2625}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2625,"lines":[{"gurmukhi":"ਬੁਬੀਂ ਕੁਦਰਤੇ ਕਿਰਦਗਾਰੇ ਜਹਾਂ।","roman":"Bubeen kudarte kiradgaare jahaan |","meaning_en":"","page":2625},{"gurmukhi":"ਕਿ ਈਂ ਰਾ ਬ ਬਖ਼ਸ਼ੀਦ ਕੁਸਤਸ਼ ਅਜ਼ਾਂ। ੭੬।","roman":"Ki een raa ba bakhsheed kustash azaan | 76 |","meaning_en":"","page":2625}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":2625,"lines":[{"gurmukhi":"ਬਿ ਰਫ਼ਤੰਦ ਹਰਦੋ ਬ ਹੁਕਮੇ ਅਮੀਰ।","roman":"Bi raftand hardo ba hukme ameer |","meaning_en":"","page":2625},{"gurmukhi":"ਯਕੇ ਸ਼ਾਹਜ਼ਾਦਹ ਬ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ। ੭੭।","roman":"Yake shaahzaadah ba dukhtar vazeer | 77 |","meaning_en":"","page":2625}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2625,"lines":[{"gurmukhi":"ਬਿ ਅਫ਼ਤਾਦ ਹਰ ਦੋ ਬ ਦਸਤੇ ਅਜ਼ੀਮ।","roman":"Bi aftaad har do ba daste azeem |","meaning_en":"","page":2625},{"gurmukhi":"ਨ ਸ਼ਾਯਦ ਦਿਗਰ ਦੀਦ ਜੁਜ਼ ਯਕ ਕਰੀਮ। ੭੮।","roman":"Na shaayad digar deed juz yak kareem | 78 |","meaning_en":"","page":2625}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2625,"lines":[{"gurmukhi":"ਬ ਮੁਲਕੇ ਹਬਸ਼ ਆਮਦ ਆਂ ਨੇਕ ਖ਼ੋਇ।","roman":"Ba mulke habash aamad aan nek khoi |","meaning_en":"","page":2625},{"gurmukhi":"ਯਕੇ ਸ਼ਾਹਜ਼ਾਦਹ ਦਿਗਰ ਖ਼ੂਬ ਰੋਇ। ੭੯।","roman":"Yake shaahzaadah digar khoob roi | 79 |","meaning_en":"","page":2625}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2625,"lines":[{"gurmukhi":"ਦਰ ਆਂ ਜਾ ਬਿਆਮਦ ਕਿ ਬਿਨਸ਼ਸਤਹ ਸ਼ਾਹ।","roman":"Dar aan jaa biaamad ki binshastah shaah |","meaning_en":"","page":2625},{"gurmukhi":"ਨਸ਼ਸਤੰਦ ਸ਼ਬ ਰੰਗ ਜ਼ਰਰੀਂ ਕੁਲਾਹ। ੮੦।","roman":"Nashastand shab rang zarreen kulaah | 80 |","meaning_en":"","page":2625}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2625,"lines":[{"gurmukhi":"ਬ ਦੀਦੰਦ ਓ ਰਾ ਬੁਖ਼ਾਦੰਦ ਪੇਸ਼।","roman":"Ba deedand o raa bukhaadand pesh |","meaning_en":"","page":2625},{"gurmukhi":"ਬ ਗੁਫ਼ਤੰਦ ਕਿ ਏ ਸ਼ੇਰ ਆਜ਼ਾਦ ਕੇਸ਼। ੮੧।","roman":"Ba guftand ki e sher aazaad kesh | 81 |","meaning_en":"","page":2625}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":2625,"lines":[{"gurmukhi":"ਜ਼ਿ ਮੁਲਕੇ ਕਦਾਮੀ ਤੁ ਬ ਮਨ ਬਗੋ।","roman":"Zi mulke kadaamee tu ba man bago |","meaning_en":"","page":2625},{"gurmukhi":"ਚਿ ਨਾਮੇ ਕਿਰਾ ਤੋ ਬ ਈਂ ਤਰਫ਼ ਜੋ। ੮੨।","roman":"Chi naame kiraa to ba een taraf jo | 82 |","meaning_en":"","page":2625}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2625,"lines":[{"gurmukhi":"ਵਗਰਨਹ ਮਰਾ ਤੋ ਨ ਗੋਈਂ ਚੁ ਰਾਸਤ।","roman":"Vagarnah maraa to na goeen chu raasat |","meaning_en":"","page":2625},{"gurmukhi":"ਕਿ ਮੁਰਦਨ ਸ਼ਿਤਾਬ ਅਸਤ ਏਜ਼ਦ ਗਵਾਹਸਤ। ੮੩।","roman":"Ki murdan shitaab asat ezad gavaahsat | 83 |","meaning_en":"","page":2625}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2625,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਿ ਪਿਸਰੇ ਮਮਾਯੰਦਰਾਂ।","roman":"Shahinshaahi pisre mamaayandraan |","meaning_en":"","page":2625},{"gurmukhi":"ਕਿ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ ਅਸਤ ਈਂ ਨੌਜਵਾਂ। ੮੪।","roman":"Ki dukhtar vazeer asat een naujvaan | 84 |","meaning_en":"","page":2625}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2625,"lines":[{"gurmukhi":"ਹਕੀਕਤ ਬ ਗੁਫ਼ਤਸ਼ ਜ਼ਿ ਪੇਸ਼ੀਨਹ ਹਾਲ।","roman":"Hakeekat ba guftash zi pesheenah haal |","meaning_en":"","page":2625},{"gurmukhi":"ਕਿ ਬਰਵੈ ਚੁ ਬੁਗਜ਼ਸ਼ਤ ਚੰਦੀਂ ਜ਼ਵਾਲ। ੮੫।","roman":"Ki barvai chu bugazshat chandeen zavaal | 85 |","meaning_en":"","page":2625}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2625,"lines":[{"gurmukhi":"ਬ ਮਿਹਰਸ਼ ਦਰਾਮਦ ਬਗੁਫ਼ਤ ਅਜ਼ ਜ਼ੁਬਾਂ।","roman":"Ba mihrash daraamad bagufat az zubaan |","meaning_en":"","page":2625},{"gurmukhi":"ਮਰਾ ਖ਼ਾਨਹ ਜਾਏ ਜ਼ਿ ਖ਼ੁਦ ਖ਼ਾਨਹ ਦਾਂ। ੮੬।","roman":"Maraa khaanah jaae zi khud khaanah daan | 86 |","meaning_en":"","page":2625}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2627,"lines":[{"gurmukhi":"ਵਜ਼ਾਰਤ ਖ਼ੁਦਸ਼ ਰਾ ਤੁਰਾ ਮੇ ਦਿਹਮ।","roman":"Vazaarat khudash raa turaa me diham |","meaning_en":"","page":2627},{"gurmukhi":"ਕੁਲਾਹੇ ਮੁਮਾਲਕ ਤੁ ਬਰ ਸਰ ਨਿਹਮ। ੮੭।","roman":"Kulaahe mumaalak tu bar sar niham | 87 |","meaning_en":"","page":2627}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2627,"lines":[{"gurmukhi":"ਬ ਗੁਫ਼ਤੰਦ ਈਂ ਰਾ ਵ ਕਰਦੰਦ ਵਜ਼ੀਰ।","roman":"Ba guftand een raa va kardand vazeer |","meaning_en":"","page":2627},{"gurmukhi":"ਕਿ ਨਾਮੇ ਵਜਾਂ ਬੂਦ ਰੌਸ਼ਨ ਜ਼ਮੀਰ। ੮੮।","roman":"Ki naame vajaan bood raushan zameer | 88 |","meaning_en":"","page":2627}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2627,"lines":[{"gurmukhi":"ਬ ਹਰ ਜਾ ਕਿ ਦੁਸ਼ਮਨ ਸ਼ਨਾਸਦ ਅਜ਼ੀਮ।","roman":"Ba har jaa ki dushman shanaasad azeem |","meaning_en":"","page":2627},{"gurmukhi":"ਦਵੀਦੰਦ ਬਰਵੈ ਬ ਹੁਕਮੇ ਕਰੀਮ। ੮੯।","roman":"Daveedand barvai ba hukme kareem | 89 |","meaning_en":"","page":2627}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2627,"lines":[{"gurmukhi":"ਕਿ ਖ਼ੂਨਸ਼ ਬਰੇਜ਼ੀਦ ਕਰਦੰਦ ਜ਼ੇਰ।","roman":"Ki khoonash barezeed kardand zer |","meaning_en":"","page":2627},{"gurmukhi":"ਦਿਗਰ ਜਾ ਸ਼ੁਨੀਦੇ ਦਵੀਦੇ ਦਲੇਰ। ੯੦।","roman":"Digar jaa shuneede daveede daler | 90 |","meaning_en":"","page":2627}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":2627,"lines":[{"gurmukhi":"ਬ ਹਰ ਜਾ ਕਿ ਤਰਕਸ਼ ਬਰੇਜ਼ੰਦ ਤੀਰ।","roman":"Ba har jaa ki tarkash barezand teer |","meaning_en":"","page":2627},{"gurmukhi":"ਬ ਕੁਸ਼ਤੇ ਅਦੂਰਾ ਬ ਕਰਦੇ ਅਸੀਰ। ੯੧।","roman":"Ba kushte adooraa ba karde aseer | 91 |","meaning_en":"","page":2627}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2627,"lines":[{"gurmukhi":"ਬ ਮੁਦਤ ਯਕੇ ਸਾਲ ਤਾ ਚਾਰ ਮਾਹ।","roman":"Ba mudat yake saal taa chaar maah |","meaning_en":"","page":2627},{"gurmukhi":"ਦਰਿਖ਼ਸ਼ਿੰਦਹ ਆਮਦ ਚੁ ਰਖ਼ਸ਼ਿੰਦਹ ਮਾਹ। ੯੨।","roman":"Darikhshindah aamad chu rakhshindah maah | 92 |","meaning_en":"","page":2627}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2627,"lines":[{"gurmukhi":"ਬਦੋਜ਼ੰਦ ਦੁਸ਼ਮਨ ਬਸੋਜ਼ੰਦ ਤਨ।","roman":"Badozand dushman basozand tan |","meaning_en":"","page":2627},{"gurmukhi":"ਬਯਾਦ ਆਮਦਸ਼ ਰੋਜ਼ਗਾਰੇ ਕੁਹਨ। ੯੩।","roman":"Bayaad aamdash rozgaare kuhan | 93 |","meaning_en":"","page":2627}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":2627,"lines":[{"gurmukhi":"ਬ ਗੁਫ਼ਤਸ਼ ਯਕੇ ਰੋਜ਼ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ।","roman":"Ba guftash yake roz dukhtar vazeer |","meaning_en":"","page":2627},{"gurmukhi":"ਕਿ ਏ ਸ਼ਾਹ ਸ਼ਾਹਾਨ ਰੌਸ਼ਨ ਜ਼ਮੀਰ। ੯੪।","roman":"Ki e shaah shaahaan raushan zameer | 94 |","meaning_en":"","page":2627}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2627,"lines":[{"gurmukhi":"ਬ ਯਕ ਬਾਰ ਮੁਲਕਤ ਫ਼ਰਾਮੋਸ਼ ਗਸ਼ਤ।","roman":"Ba yak baar mulkat faraamosh gashat |","meaning_en":"","page":2627},{"gurmukhi":"ਕਿ ਅਜ਼ ਮਸਤ ਮਸਤੀ ਹਮਹ ਹੋਸ਼ ਗਸ਼ਤ। ੯੫।","roman":"Ki az masat mastee hamah hosh gashat | 95 |","meaning_en":"","page":2627}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":2627,"lines":[{"gurmukhi":"ਤੁ ਆਂ ਮੁਲਕ ਪੇਸ਼ੀਨਹ ਰਾ ਯਾਦ ਕੁਨ।","roman":"Tu aan mulak pesheenah raa yaad kun |","meaning_en":"","page":2627},{"gurmukhi":"ਕਿ ਸ਼ਹਰੇ ਪਦਰ ਰਾ ਤੁ ਆਬਾਦ ਕੁਨ। ੯੬।","roman":"Ki shahre padar raa tu aabaad kun | 96 |","meaning_en":"","page":2627}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2627,"lines":[{"gurmukhi":"ਨਿਗਹ ਦਾਸ਼ਤ ਅਜ਼ ਫ਼ੌਜ ਲਸ਼ਕਰ ਤਮਾਮ।","roman":"Nigah daashat az fauj lashkar tamaam |","meaning_en":"","page":2627},{"gurmukhi":"ਬਸੇ ਗੰਜ ਬਖ਼ਸ਼ੀਦ ਬਰ ਵੈ ਮੁਦਾਮ। ੯੭।","roman":"Base ganj bakhsheed bar vai mudaam | 97 |","meaning_en":"","page":2627}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2627,"lines":[{"gurmukhi":"ਯਕੇ ਲਸ਼ਕਰ ਆਰਾਸਤ ਚੂੰ ਨੌਬਹਾਰ।","roman":"Yake lashkar aaraasat choon naubhaar |","meaning_en":"","page":2627},{"gurmukhi":"ਜ਼ਿ ਖ਼ੰਜਰ ਵ ਗੁਰਜੋ ਵ ਬਕਤਰ ਹਜ਼ਾਰ। ੯੮।","roman":"Zi khanjar va gurjo va baktar hazaar | 98 |","meaning_en":"","page":2627}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2627,"lines":[{"gurmukhi":"ਜ਼ਿਰਹ ਖ਼ੋਦ ਖ਼ੁਫ਼ਤਾਨ ਬਰਗਸ਼ਤਵਾਨ।","roman":"Zirah khod khuftaan baragshatvaan |","meaning_en":"","page":2627},{"gurmukhi":"ਜ਼ਿ ਸ਼ਮਸ਼ੇਰ ਹਿੰਦੀ ਗਿਰਾਂ ਤਾ ਗਿਰਾਨ। ੯੯।","roman":"Zi shamsher hindee giraan taa giraan | 99 |","meaning_en":"","page":2627}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2627,"lines":[{"gurmukhi":"ਜ਼ਿ ਬੰਦੂਕ ਮਸਹਦ ਵ ਚੀਨੀ ਕਮਾਨ।","roman":"Zi bandook mashad va cheenee kamaan |","meaning_en":"","page":2627},{"gurmukhi":"ਜ਼ਿਰਹ ਰੂਮ ਸ਼ਮਸ਼ੇਰ ਹਿੰਦੋਸਤਾਨ। ੧੦੦।","roman":"Zirah room shamsher hindostaan | 100 |","meaning_en":"","page":2627}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2627,"lines":[{"gurmukhi":"ਚਿ ਅਜ਼ ਤਾਜ਼ੀ ਅਸਪਾਨ ਪੋਲਾਦ ਨਾਲ।","roman":"Chi az taazee aspaan polaad naal |","meaning_en":"","page":2627},{"gurmukhi":"ਹਮਹ ਜੂ ਬਦਹ ਫ਼ੀਲਾਨ ਅਜਿਸ਼ ਬੇ ਮਸਾਲ। ੧੦੧।","roman":"Hamah joo badah feelaan ajish be masaal | 101 |","meaning_en":"","page":2627}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2627,"lines":[{"gurmukhi":"ਹਮਹ ਸ਼ੇਰ ਮਰਦਾਂ ਵ ਜ਼ੋਰਾਵਰਾਂ।","roman":"Hamah sher mardaan va zoraavraan |","meaning_en":"","page":2627},{"gurmukhi":"ਕਿ ਸ਼ੇਰ ਅਫ਼ਕਨਾ ਰਾ ਬਸ਼ਫ਼ ਅਫ਼ਕਨਾਂ। ੧੦੨।","roman":"Ki sher afaknaa raa bashaf afaknaan | 102 |","meaning_en":"","page":2627}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2629,"lines":[{"gurmukhi":"ਬਰਜ਼ਮ ਅੰਦਰੂੰ ਹਮਚੁ ਪੀਲ ਅਫ਼ਕਨ ਅਸਤ।","roman":"Barzam androon hamchu peel afkan asat |","meaning_en":"","page":2629},{"gurmukhi":"ਬਬਜ਼ਮ ਅੰਦਰੂੰ ਚਰਬ ਚਾਲਾਕ ਦਸਤ। ੧੦੩।","roman":"Babzam androon charab chaalaak dasat | 103 |","meaning_en":"","page":2629}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2629,"lines":[{"gurmukhi":"ਨਿਸ਼ਾਂ ਮੇ ਦਿਹਦ ਨੇਜ਼ਹ ਰਾ ਨੋਕ ਖ਼ੂੰ।","roman":"Nishaan me dihad nezah raa nok khoon |","meaning_en":"","page":2629},{"gurmukhi":"ਕਸ਼ੀਦੰਦ ਅਜ਼ ਤੇਗ ਜ਼ਹਿਰ ਆਬ ਗੂੰ। ੧੦੪।","roman":"Kasheedand az teg zahir aab goon | 104 |","meaning_en":"","page":2629}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2629,"lines":[{"gurmukhi":"ਯਕੇ ਫ਼ੌਜ ਆਰਾਸਤਹ ਹਮ ਚੁ ਕੋਹ।","roman":"Yake fauj aaraastah ham chu koh |","meaning_en":"","page":2629},{"gurmukhi":"ਜੁਵਾਨਾਨ ਸ਼ਾਇਸਤਹੇ ਯਕ ਗਰੋਹ। ੧੦੫।","roman":"Juvaanaan shaaisathe yak garoh | 105 |","meaning_en":"","page":2629}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2629,"lines":[{"gurmukhi":"ਬਪੋਸ਼ੀਦ ਦਸਤਾਰ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ।","roman":"Baposheed dastaar dukhtar vazeer |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਬਸਤੰਦ ਸ਼ਮਸ਼ੇਰ ਜੁਸਤੰਦ ਤੀਰ। ੧੦੬।","roman":"Ba bastand shamsher justand teer | 106 |","meaning_en":"","page":2629}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2629,"lines":[{"gurmukhi":"ਬ ਸਰਦਾਰੀਏ ਕਰਦ ਪੇਸ਼ੀਨਹ ਫ਼ੌਜ।","roman":"Ba sardaaree'e karad pesheenah fauj |","meaning_en":"","page":2629},{"gurmukhi":"ਰਵਾਂ ਕਰਦ ਲਸ਼ਕਰ ਚੁ ਦਰੀਯਾਇ ਮੌਜ। ੧੦੭।","roman":"Ravaan karad lashkar chu dareeyaai mauj | 107 |","meaning_en":"","page":2629}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2629,"lines":[{"gurmukhi":"ਯਕੇ ਗੋਲ ਬਸਤਹ ਚੁ ਅਬਰੇ ਸਿਯਾਹ।","roman":"Yake gol bastah chu abre siyaah |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਲਰਜ਼ੀਦ ਬੂਮੋ ਬ ਲਰਜ਼ੀਦ ਮਾਹ। ੧੦੮।","roman":"Ba larzeed boomo ba larzeed maah | 108 |","meaning_en":"","page":2629}]},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2629,"lines":[{"gurmukhi":"ਬਿਯਾਵੁਰਦ ਲਸ਼ਕਰ ਚੁ ਬਰ ਵੈ ਹਦੂਦ।","roman":"Biyaavurad lashkar chu bar vai hadood |","meaning_en":"","page":2629},{"gurmukhi":"ਸਲਾਹੇ ਦਿਗਰ ਤੀਰ ਤੇਗੋ ਨਮੂਦ। ੧੦੯।","roman":"Salaahe digar teer tego namood | 109 |","meaning_en":"","page":2629}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2629,"lines":[{"gurmukhi":"ਬਿਆਰਾਸਤ ਲਸ਼ਕਰ ਬ ਸਾਜ਼ੇ ਤਮਾਮ।","roman":"Biaaraasat lashkar ba saaze tamaam |","meaning_en":"","page":2629},{"gurmukhi":"ਹਮਹ ਖ਼ੰਜਰੋ ਗੁਰਜ ਗੋਪਾਲ ਨਾਮ। ੧੧੦।","roman":"Hamah khanjro guraj gopaal naam | 110 |","meaning_en":"","page":2629}]},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":2629,"lines":[{"gurmukhi":"ਬ ਬੁਰਦੰਦ ਅਕਲੀਮ ਤਾ ਰਾਜ ਤਖ਼ਤ।","roman":"Ba burdand akleem taa raaj takhat |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਬੁਰਦਨ ਸ਼ਹੇ ਬਾਦ ਪਾਯਾਨ ਰਖ਼ਤ। ੧੧੧।","roman":"Ba burdan shahe baad paayaan rakhat | 111 |","meaning_en":"","page":2629}]},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":2629,"lines":[{"gurmukhi":"ਚੁਨਾ ਜੰਗ ਕਰਦੰਦ ਆਂ ਮੁਲਕ ਰਾ।","roman":"Chunaa jang kardand aan mulak raa |","meaning_en":"","page":2629},{"gurmukhi":"ਚੁ ਬਰਗੇ ਦਰਖ਼ਤਾਂ ਜ਼ਿ ਬਾਦੇ ਸਬਾ। ੧੧੨।","roman":"Chu barge darakhtaan zi baade sabaa | 112 |","meaning_en":"","page":2629}]},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":2629,"lines":[{"gurmukhi":"ਬ ਕੁਸ਼ਤਨ ਅਦੂਰਾ ਕੁਸ਼ਾਯਦ ਬ ਪੇਸ਼।","roman":"Ba kushtan adooraa kushaayad ba pesh |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਬੇਰੂੰ ਜ਼ਿ ਮੁਲਕਸ਼ ਹਮਹ ਰੂਹ ਰੇਸ਼। ੧੧੩।","roman":"Ba beroon zi mulkash hamah rooh resh | 113 |","meaning_en":"","page":2629}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":2629,"lines":[{"gurmukhi":"ਪਰੀ ਚਿਹਰਏ ਹਮ ਚੁ ਸ਼ੇਰੇ ਨਿਯਾਦ।","roman":"Paree chihrae ham chu shere niyaad |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਕੁਸ਼ਤਨ ਅਦੂਰਾ ਕਿ ਖ਼ੰਜਰ ਕੁਸ਼ਾਦ। ੧੧੪।","roman":"Ba kushtan adooraa ki khanjar kushaad | 114 |","meaning_en":"","page":2629}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":2629,"lines":[{"gurmukhi":"ਬ ਹਰ ਜਾ ਦਵੀਦੇ ਬ ਕੁਸ਼ਤੇ ਅਜ਼ਾਂ।","roman":"Ba har jaa daveede ba kushte azaan |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਹਰ ਜਾ ਰਸ਼ੀਦੇ ਬ ਬਸਤੇ ਅਜ਼ਾਂ। ੧੧੫।","roman":"Ba har jaa rasheede ba baste azaan | 115 |","meaning_en":"","page":2629}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":2629,"lines":[{"gurmukhi":"ਸ਼ੁਨੀਦ ਈਂ ਅਜ਼ਾਂ ਸ਼ਾਹਿ ਮਾਯੰਦਰਾਂ।","roman":"Shuneed een azaan shaahi maayandraan |","meaning_en":"","page":2629},{"gurmukhi":"ਬ ਤੁੰਦੀ ਦਰਾਮਦ ਬਜਾਇਸ਼ ਹੁਮਾਂ। ੧੧੬।","roman":"Ba tundee daraamad bajaaish humaan | 116 |","meaning_en":"","page":2629}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":2629,"lines":[{"gurmukhi":"ਬ ਆਰਾਸਤਹ ਫ਼ੌਜ ਚੂੰ ਨੌਬਹਾਰ।","roman":"Ba aaraastah fauj choon naubhaar |","meaning_en":"","page":2629},{"gurmukhi":"ਜ਼ਿ ਤੋਪੇ ਤੁਪਕ ਖ਼ੰਜਰੇ ਆਬਦਾਰ। ੧੧੭।","roman":"Zi tope tupak khanjre aabdaar | 117 |","meaning_en":"","page":2629}]},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":2629,"lines":[{"gurmukhi":"ਬਪੇਸ਼ੇ ਸ਼ਫ਼ ਆਮਦ ਚੁ ਦਰਯਾ ਅਮੀਕ।","roman":"Bapeshe shaf aamad chu daryaa ameek |","meaning_en":"","page":2629},{"gurmukhi":"ਜ਼ਿ ਸਰਤਾ ਕਦਮ ਹਮ ਚੁ ਆਹਨ ਗਰੀਕ। ੧੧੮।","roman":"Zi sartaa kadam ham chu aahan gareek | 118 |","meaning_en":"","page":2629}]},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":2631,"lines":[{"gurmukhi":"ਬ ਆਵਾਜ਼ ਤੋਪੋ ਤਮਾਚਹ ਤੁਫ਼ੰਗ।","roman":"Ba aavaaz topo tamaachah tufang |","meaning_en":"","page":2631},{"gurmukhi":"ਜ਼ਿਮੀ ਗਸ਼ਤ ਹਮ ਚੂੰ ਗੁਲੇ ਲਾਲਹ ਰੰਗ। ੧੧੯।","roman":"Zimee gashat ham choon gule laalah rang | 119 |","meaning_en":"","page":2631}]},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":2631,"lines":[{"gurmukhi":"ਬਮੈਦਾਂ ਦਰਾਮਦ ਕਿ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ।","roman":"Bamaidaan daraamad ki dukhtar vazeer |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਯਕ ਦਸਤ ਚੀਨੀ ਕਮਾਂ ਦਸਤ ਤੀਰ। ੧੨੦।","roman":"Ba yak dasat cheenee kamaan dasat teer | 120 |","meaning_en":"","page":2631}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":2631,"lines":[{"gurmukhi":"ਬ ਹਰਜਾ ਕਿ ਪਰਰਾਂ ਸ਼ਵਦ ਤੀਰ ਦਸਤ।","roman":"Ba harjaa ki parraan shavad teer dasat |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਸਦ ਪਹਿਲੂਏ ਪੀਲ ਮਰਦਾਂ ਗੁਜ਼ਸ਼ਤ। ੧੨੧।","roman":"Ba sad pahilooe peel mardaan guzshat | 121 |","meaning_en":"","page":2631}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":2631,"lines":[{"gurmukhi":"ਚੁਨਾ ਮੌਜ਼ ਖ਼ੇਜ਼ਦ ਜ਼ਿ ਦਰੀਯਾਬ ਸੰਗ।","roman":"Chunaa mauz khezad zi dareeyaab sang |","meaning_en":"","page":2631},{"gurmukhi":"ਬਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਚੁ ਤੇਗੋ ਨਿਹੰਗ। ੧੨੨।","roman":"Barkhash andar aamad chu tego nihang | 122 |","meaning_en":"","page":2631}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":2631,"lines":[{"gurmukhi":"ਬ ਤਾਬਸ਼ ਦਰਾਮਦ ਯਕੇ ਤਾਬ ਨਾਕ।","roman":"Ba taabash daraamad yake taab naak |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਯਕੇ ਖ਼ੂਨ ਖ਼ਾਕ। ੧੨੩।","roman":"Ba rakhash andar aamad yake khoon khaak | 123 |","meaning_en":"","page":2631}]},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":2631,"lines":[{"gurmukhi":"ਬ ਤਾਮਸ਼ ਦਰਾਮਦ ਹਮਹ ਹਿੰਦ ਤੇਗ।","roman":"Ba taamash daraamad hamah hind teg |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਗੁਰਰੀਦ ਲਸ਼ਕਰ ਚੁ ਦਰੀਯਾਇ ਮੇਗ। ੧੨੪।","roman":"Ba gurreed lashkar chu dareeyaai meg | 124 |","meaning_en":"","page":2631}]},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":2631,"lines":[{"gurmukhi":"ਬ ਚਰਖ਼ ਅੰਦਰ ਆਮਦ ਬ ਚੀਨੀ ਕਮਾਂ।","roman":"Ba charakh andar aamad ba cheenee kamaan |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਤਾਬ ਆਮਦਸ਼ ਤੇਗ ਹਿੰਦੋਸਤਾਂ। ੧੨੫।","roman":"Ba taab aamdash teg hindostaan | 125 |","meaning_en":"","page":2631}]},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":2631,"lines":[{"gurmukhi":"ਗਰੇਵਹ ਬਬਾਵੁਰਦ ਚੰਦੀ ਕਰੋਹ।","roman":"Garevah babaavurad chandee karoh |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਲਰਜ਼ੀਦ ਦਰਯਾਬ ਦਰਰੀਦ ਕੋਹ। ੧੨੬।","roman":"Ba larzeed daryaab darreed koh | 126 |","meaning_en":"","page":2631}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":2631,"lines":[{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਜ਼ਿਮੀਨੋ ਜ਼ਮਾਂ।","roman":"Ba rakhash andar aamad zimeeno zamaan |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਤਾਬਸ਼ ਦਰਾਮਦ ਚੁ ਤੇਗੇ ਯਮਾਂ। ੧੨੭।","roman":"Ba taabash daraamad chu tege yamaan | 127 |","meaning_en":"","page":2631}]},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":2631,"lines":[{"gurmukhi":"ਬ ਤੇਜ਼ ਆਮਦੋ ਨੇਜ਼ਹੇ ਬਾਂਸਤੀਂ।","roman":"Ba tez aamdo nezhe baansteen |","meaning_en":"","page":2631},{"gurmukhi":"ਬ ਜੁੰਬਸ਼ ਦਰਾਮਦ ਤਨੇ ਨਾਜ਼ਨੀਂ। ੧੨੮।","roman":"Ba junbash daraamad tane naazneen | 128 |","meaning_en":"","page":2631}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":2631,"lines":[{"gurmukhi":"ਬ ਸ਼ੋਰਸ਼ ਦਰਾਮਦ ਨਫ਼ਰ ਹਾਇ ਕੁਹਿਰ।","roman":"Ba shorash daraamad nafar haai kuhir |","meaning_en":"","page":2631},{"gurmukhi":"ਜ਼ਿ ਤੋਪੋ ਵ ਨੇਜ਼ਹ ਬਪੋਸ਼ੀਦ ਦਹਿਰ। ੧੨੯।","roman":"Zi topo va nezah baposheed dahir | 129 |","meaning_en":"","page":2631}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":2631,"lines":[{"gurmukhi":"ਬ ਜੁੰਬਸ਼ ਦਰਾਮਦ ਕਮਾਨੋ ਕਮੰਦ।","roman":"Ba junbash daraamad kamaano kamand |","meaning_en":"","page":2631},{"gurmukhi":"ਦਰਖ਼ਸ਼ਾਂ ਸ਼ੁਦਹ ਤੇਗ ਸੀਮਾਬ ਤੁੰਦ। ੧੩੦।","roman":"Darakhshaan shudah teg seemaab tund | 130 |","meaning_en":"","page":2631}]},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":2631,"lines":[{"gurmukhi":"ਬ ਜੋਸ਼ ਆਮਦਹ ਖ਼ੰਜਰੇ ਖ਼੍ਵਾਰ ਖ਼ੂੰ।","roman":"Ba josh aamdah khanjre khvaar khoon |","meaning_en":"","page":2631},{"gurmukhi":"ਜ਼ੁਬਾਂ ਨੇਜ਼ਹ ਮਾਰਸ਼ ਬਰਾਮਦ ਬਰੂੰ। ੧੩੧।","roman":"Zubaan nezah maarash baraamad baroon | 131 |","meaning_en":"","page":2631}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":2631,"lines":[{"gurmukhi":"ਬ ਤਾਬਸ਼ ਦਰਾਮਦ ਲਕੋ ਤਾਬ ਨਾਕ।","roman":"Ba taabash daraamad lako taab naak |","meaning_en":"","page":2631},{"gurmukhi":"ਯਕੇ ਸੁਰਖ਼ ਗੋਗਿਰਦ ਸ਼ੁਦ ਖੂੰਨ ਖ਼ਾਕ। ੧੩੨।","roman":"Yake surakh gogirad shud khoonn khaak | 132 |","meaning_en":"","page":2631}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":2631,"lines":[{"gurmukhi":"ਦਿਹਾ ਦਿਹ ਦਰਾਮਦ ਜ਼ਿ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Dihaa dih daraamad zi teero tufang |","meaning_en":"","page":2631},{"gurmukhi":"ਹਯਾਹਯ ਦਰਾਮਦ ਨਿਹੰਗੋ ਨਿਹੰਗ। ੧੩੩।","roman":"Hayaahay daraamad nihango nihang | 133 |","meaning_en":"","page":2631}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":2631,"lines":[{"gurmukhi":"ਚਕਾਚਾਕ ਬਰਖ਼ਾਸਤ ਤੀਰੋ ਕਮਾਂ।","roman":"Chakaachaak barkhaasat teero kamaan |","meaning_en":"","page":2631},{"gurmukhi":"ਬਰਾਮਦ ਯਕੇ ਰੁਸਤ ਖ਼ੇਜ਼ ਅਜ਼ ਜਹਾਂ। ੧੩੪।","roman":"Baraamad yake rusat khez az jahaan | 134 |","meaning_en":"","page":2631}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":2633,"lines":[{"gurmukhi":"ਨ ਪੋਯਿੰਦਰ ਰਾ ਬਰ ਜ਼ਿਮੀ ਬੂਦ ਜਾ।","roman":"Na poyindar raa bar zimee bood jaa |","meaning_en":"","page":2633},{"gurmukhi":"ਨ ਪਰਿੰਦਹ ਰਾ ਦਰ ਹਵਾ ਬੂਦ ਰਾਹ। ੧੩੫।","roman":"Na parindah raa dar havaa bood raah | 135 |","meaning_en":"","page":2633}]},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":2633,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੇਗ ਬਾਰੀਦ ਮਿਯਾਨੇ ਮੁਸਾਫ਼।","roman":"Chunaa teg baareed miyaane musaaf |","meaning_en":"","page":2633},{"gurmukhi":"ਕਿ ਅਜ਼ ਕੁਸ਼ਤਗਾਂ ਸ਼ੁਦ ਜ਼ਿਮੀ ਕੋਹਕਾਫ਼। ੧੩੬।","roman":"Ki az kushatgaan shud zimee kohkaaf | 136 |","meaning_en":"","page":2633}]},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":2633,"lines":[{"gurmukhi":"ਕਿ ਪਾਓ ਸਰ ਅੰਬੋਹ ਚੰਦਾਂ ਸ਼ੁਦਹ।","roman":"Ki paao sar anboh chandaan shudah |","meaning_en":"","page":2633},{"gurmukhi":"ਕਿ ਮੈਦਾਂ ਪੁਰ ਅਜ਼ ਗੋਇ ਚੌਗਾਂ ਸ਼ੁਦਹ। ੧੩੭।","roman":"Ki maidaan pur az goi chaugaan shudah | 137 |","meaning_en":"","page":2633}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":2633,"lines":[{"gurmukhi":"ਰਵਾ ਰਉ ਦਰਾਮਦ ਬ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Ravaa rau daraamad ba teero tufang |","meaning_en":"","page":2633},{"gurmukhi":"ਕਿ ਪਾਰਹ ਸ਼ੁਦਹ ਖ਼ੋਦ ਖ਼ੁਫ਼ਤਾਨ ਜੰਗ। ੧੩੮।","roman":"Ki paarah shudah khod khuftaan jang | 138 |","meaning_en":"","page":2633}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":2633,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੇਗ ਤਾਬਸ਼ ਤ ਪੀਦ ਆਫ਼ਤਾਬ।","roman":"Chunaa teg taabash ta peed aaftaab |","meaning_en":"","page":2633},{"gurmukhi":"ਦਰਖ਼ਤਾਂ ਸ਼ੁਦਹ ਖ਼ੁਸ਼ਕ ਵ ਦਰਯਾਇ ਆਬ। ੧੩੯।","roman":"Darakhtaan shudah khushak va daryaai aab | 139 |","meaning_en":"","page":2633}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":2633,"lines":[{"gurmukhi":"ਚੁਨਾਂ ਤੀਰ ਬਾਰਾਂ ਸ਼ੁਦਹ ਹਮ ਚੁ ਬਰਕੁ।","roman":"Chunaan teer baaraan shudah ham chu barku |","meaning_en":"","page":2633},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਸ਼ੁਦ ਫ਼ੀਲ ਚੂੰ ਫ਼ਰਕ ਫ਼ਰਕ। ੧੪੦।","roman":"Biaftaad shud feel choon farak farak | 140 |","meaning_en":"","page":2633}]},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":2633,"lines":[{"gurmukhi":"ਬ ਹਰਬ ਅੰਦਰ ਆਮਦ ਵਜ਼ੀਰੇ ਚੁ ਬਾਦ।","roman":"Ba harab andar aamad vazeere chu baad |","meaning_en":"","page":2633},{"gurmukhi":"ਯਕੇ ਤੇਗ ਮਾਯੰਦਰਾਨੀ ਕੁਸ਼ਾਦ। ੧੪੧।","roman":"Yake teg maayandraanee kushaad | 141 |","meaning_en":"","page":2633}]},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":2633,"lines":[{"gurmukhi":"ਦਿਗਰ ਤਰਫ਼ ਆਮਦ ਬ ਦੁਖ਼ਤਰ ਅਜ਼ਾਂ।","roman":"Digar taraf aamad ba dukhtar azaan |","meaning_en":"","page":2633},{"gurmukhi":"ਬਰਹਿਨੇ ਯਕੇ ਤੇਗ ਹਿੰਦੋਸਤਾਂ। ੧੪੨।","roman":"Barhine yake teg hindostaan | 142 |","meaning_en":"","page":2633}]},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":2633,"lines":[{"gurmukhi":"ਦਰਖ਼ਸ਼ਾਂ ਸ਼ੁਦਹ ਆਂ ਚੁਨਾ ਤੇਗ ਤੇਜ਼।","roman":"Darakhshaan shudah aan chunaa teg tez |","meaning_en":"","page":2633},{"gurmukhi":"ਅਦੂਰਾ ਅਜ਼ੋ ਦਿਲ ਸ਼ਵਦ ਰੇਜ਼ ਰੇਜ਼। ੧੪੩।","roman":"Adooraa azo dil shavad rez rez | 143 |","meaning_en":"","page":2633}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":2633,"lines":[{"gurmukhi":"ਯਕੇ ਤੇਗ ਜ਼ਦ ਬਰ ਸਰੇ ਓ ਸਮੰਦ।","roman":"Yake teg zad bar sare o samand |","meaning_en":"","page":2633},{"gurmukhi":"ਜ਼ਿਮੀਨਸ਼ ਦਰਾਮਦ ਚੁ ਕੋਹੇ ਬਿਲੰਦ। ੧੪੪।","roman":"Zimeenash daraamad chu kohe biland | 144 |","meaning_en":"","page":2633}]},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":2633,"lines":[{"gurmukhi":"ਦਿਗਰ ਤੇਗ ਓ ਰਾ ਬਿਜ਼ਦ ਕਰਦ ਨੀਮ।","roman":"Digar teg o raa bizad karad neem |","meaning_en":"","page":2633},{"gurmukhi":"ਬਿ ਅਫ਼ਤਾਦ ਬੂਮਸ ਚੁ ਕਰਖੇ ਅਜ਼ੀਮ। ੧੪੫।","roman":"Bi aftaad boomas chu karkhe azeem | 145 |","meaning_en":"","page":2633}]},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":2633,"lines":[{"gurmukhi":"ਦਿਗਰ ਮਰਦ ਆਮਦ ਚੁ ਪ੍ਰਰਾਂ ਉਕਾਬ।","roman":"Digar marad aamad chu praraan ukaab |","meaning_en":"","page":2633},{"gurmukhi":"ਬਿਜ਼ਦ ਤੇਗ ਓ ਰਾ ਬ ਕਰਦਸ਼ ਖ਼ਰਾਬ। ੧੪੬।","roman":"Bizad teg o raa ba kardash kharaab | 146 |","meaning_en":"","page":2633}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":2633,"lines":[{"gurmukhi":"ਚੁ ਕਾਰੇ ਵਜ਼ੀਰਸ਼ ਬਰਾਹਤ ਰਸੀਦ।","roman":"Chu kaare vazeerash baraahat raseed |","meaning_en":"","page":2633},{"gurmukhi":"ਦਿਗਰ ਮਿਹਨਤੇ ਸਿਯਮ ਆਮਦ ਪਦੀਦ। ੧੪੭।","roman":"Digar mihante siyam aamad padeed | 147 |","meaning_en":"","page":2633}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":2633,"lines":[{"gurmukhi":"ਸਿਯਮ ਦੇਵ ਆਮਦ ਬਗਲ ਤੀਦ ਖ਼ੂੰ।","roman":"Siyam dev aamad bagal teed khoon |","meaning_en":"","page":2633},{"gurmukhi":"ਜ਼ਿ ਦਹਲੀਜ਼ ਦੋਜ਼ਖ਼ ਬਰਾਮਦ ਬਰੂੰ। ੧੪੮।","roman":"Zi dahleez dozakh baraamad baroon | 148 |","meaning_en":"","page":2633}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":2633,"lines":[{"gurmukhi":"ਬ ਕੁਸ਼ਤੰਦ ਓ ਰਾ ਦੁ ਕਰਦੰਦ ਤਨ।","roman":"Ba kushtand o raa du kardand tan |","meaning_en":"","page":2633},{"gurmukhi":"ਚੁ ਸ਼ੇਰੇ ਯਿਆਂ ਹਮ ਚੁ ਗੋਰੇ ਕੁਹਨ। ੧੪੯।","roman":"Chu shere yiaan ham chu gore kuhan | 149 |","meaning_en":"","page":2633}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":2633,"lines":[{"gurmukhi":"ਚਹਾਰਮ ਦਰਾਮਦ ਚੁ ਸ਼ੇਰਾਂ ਬਜੰਗ।","roman":"Chahaaram daraamad chu sheraan bajang |","meaning_en":"","page":2633},{"gurmukhi":"ਚੁ ਬਰ ਬਚਹੇ ਗੋਰ ਗਰਰਾਂ ਪਿਲੰਗ। ੧੫੦।","roman":"Chu bar bachhe gor garraan pilang | 150 |","meaning_en":"","page":2633}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":2635,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੇਗ ਬਰ ਵੈ ਬਿਜ਼ਦ ਨਾਜ਼ਨੀਂ।","roman":"Chunaa teg bar vai bizad naazneen |","meaning_en":"","page":2635},{"gurmukhi":"ਕਿ ਅਜ਼ ਪੁਸ਼ਤ ਅਸਪਸ਼ ਦਰਾਮਦ ਜ਼ਿਮੀਂ। ੧੫੧।","roman":"Ki az pushat aspash daraamad zimeen | 151 |","meaning_en":"","page":2635}]},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":2635,"lines":[{"gurmukhi":"ਕਿ ਪੰਚਮ ਦਰਾਮਦ ਚੁ ਦੇਵੇ ਅਜ਼ੀਮ।","roman":"Ki pancham daraamad chu deve azeem |","meaning_en":"","page":2635},{"gurmukhi":"ਯਕੇ ਜ਼ਖ਼ਮ ਜ਼ਦ ਕਰਦ ਹੁਕਮੇ ਕਰੀਮ। ੧੫੨।","roman":"Yake zakham zad karad hukme kareem | 152 |","meaning_en":"","page":2635}]},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":2635,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੇਗ ਬਰ ਵੈ ਜ਼ਦਾਂ ਖ਼ੂਬ ਰੰਗ।","roman":"Chunaa teg bar vai zadaan khoob rang |","meaning_en":"","page":2635},{"gurmukhi":"ਜ਼ਿ ਸਰ ਤਾ ਕਦਮ ਆਮਦਹ ਜ਼ੇਰ ਤੰਗ। ੧੫੩।","roman":"Zi sar taa kadam aamdah zer tang | 153 |","meaning_en":"","page":2635}]},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":2635,"lines":[{"gurmukhi":"ਸ਼ਸ਼ਮ ਦੇਵ ਆਮਦ ਚੁ ਅਫ਼ਰੀਤ ਮਸਤ।","roman":"Shasham dev aamad chu afreet masat |","meaning_en":"","page":2635},{"gurmukhi":"ਜ਼ਿ ਤੀਰੇ ਕਮਾਂ ਹਮ ਚੁ ਕਬਜ਼ਹ ਗੁਜ਼ਸ਼ਤ। ੧੫੪।","roman":"Zi teere kamaan ham chu kabzah guzshat | 154 |","meaning_en":"","page":2635}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":2635,"lines":[{"gurmukhi":"ਬਿਜ਼ਦ ਤੇਗ ਓ ਰਾ ਕਿ ਓ ਨੀਮ ਸ਼ੁਦ।","roman":"Bizad teg o raa ki o neem shud |","meaning_en":"","page":2635},{"gurmukhi":"ਕਿ ਦੀਗਰ ਯਲਾ ਰਾ ਅਜ਼ੋ ਬੀਮ ਸ਼ੁਦ। ੧੫੫।","roman":"Ki deegar yalaa raa azo beem shud | 155 |","meaning_en":"","page":2635}]},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":2635,"lines":[{"gurmukhi":"ਚੁਨੀ ਤਾ ਬਮਿਕਦਾਰ ਹਫ਼ਤਾਦ ਮਰਦ।","roman":"Chunee taa bamikdaar haftaad marad |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਤੇਗ ਅੰਦਰ ਆਵੇਖ਼ਤ ਖ਼ਾਸ ਅਜ਼ ਨ ਬਰਦ। ੧੫੬।","roman":"Ba teg andar aavekhat khaas az na barad | 156 |","meaning_en":"","page":2635}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":2635,"lines":[{"gurmukhi":"ਦਿਗਰ ਕਸ ਨਿਆਮਦ ਤਮੰਨਾਇ ਜੰਗ।","roman":"Digar kas niaamad tamannaai jang |","meaning_en":"","page":2635},{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਨਿਯਾਮਦ ਦਿਲਾਵਰ ਨਿਹੰਗ। ੧੫੭।","roman":"Ki beroon niyaamad dilaavar nihang | 157 |","meaning_en":"","page":2635}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":2635,"lines":[{"gurmukhi":"ਬ ਹਰਬ ਆਮਦਸ਼ ਸ਼ਾਹ ਮਾਯੰਦਰਾਂ।","roman":"Ba harab aamdash shaah maayandraan |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਤਾਬਸ਼ ਤਪੀਦਨ ਦਿਲੇ ਮਰਦਮਾਂ। ੧੫੮।","roman":"Ba taabash tapeedan dile maradmaan | 158 |","meaning_en":"","page":2635}]},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":2635,"lines":[{"gurmukhi":"ਚੁ ਅਬਰਸ ਬ ਅੰਦਾਖ਼ਤ ਦਉਰੇ ਯਲਾਂ।","roman":"Chu abras ba andaakhat daure yalaan |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਜ਼ਿਹੇ ਆਸਮਾਂ। ੧੫੯।","roman":"Ba rakhash andar aamad zihe aasmaan | 159 |","meaning_en":"","page":2635}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":2635,"lines":[{"gurmukhi":"ਬ ਤਾਬਸ਼ ਦਰਾਮਦ ਜ਼ਿਮੀਨੋ ਜ਼ਮਨ।","roman":"Ba taabash daraamad zimeeno zaman |","meaning_en":"","page":2635},{"gurmukhi":"ਦਰਖ਼ਸ਼ਾਂ ਸ਼ੁਦਹ ਤੇਗ ਹਿੰਦੀ ਯਮਨ। ੧੬੦।","roman":"Darakhshaan shudah teg hindee yaman | 160 |","meaning_en":"","page":2635}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":2635,"lines":[{"gurmukhi":"ਚਲਾਚਲ ਦਰਾਮਦ ਕਮਾਨੋ ਕਮੰਦ।","roman":"Chalaachal daraamad kamaano kamand |","meaning_en":"","page":2635},{"gurmukhi":"ਹਯਾਹਯ ਦਰਾਮਦ ਬ ਗੁਰਜੋ ਗਜ਼ੰਦ। ੧੬੧।","roman":"Hayaahay daraamad ba gurjo gazand | 161 |","meaning_en":"","page":2635}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":2635,"lines":[{"gurmukhi":"ਚਕਾਚਾਕ ਬਰਖ਼ਾਸਤ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Chakaachaak barkhaasat teero tufang |","meaning_en":"","page":2635},{"gurmukhi":"ਜ਼ਿਮੀ ਲਾਲ ਸ਼ੁਦ ਚੂੰ ਗੁਲੇ ਲਾਲਹ ਰੰਗ। ੧੬੨।","roman":"Zimee laal shud choon gule laalah rang | 162 |","meaning_en":"","page":2635}]},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":2635,"lines":[{"gurmukhi":"ਹਹਾਹੂ ਦਰਾਮਦ ਚੁਪਹ ਨੰਦ ਰੂੰ।","roman":"Hahaahoo daraamad chupah nand roon |","meaning_en":"","page":2635},{"gurmukhi":"ਦਿਹਾ ਦਿਹ ਸ਼ੁਦਹ ਖ਼ੰਜਰੇ ਖ਼ਾਰ ਖੂੰ। ੧੬੩।","roman":"Dihaa dih shudah khanjre khaar khoon | 163 |","meaning_en":"","page":2635}]},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":2635,"lines":[{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਯਕੇ ਤਾਬ ਰੰਗ।","roman":"Ba rakhash andar aamad yake taab rang |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਦੁ ਚਾਲਾਕ ਜੰਗ। ੧੬੪।","roman":"Ba rakhash andar aamad du chaalaak jang | 164 |","meaning_en":"","page":2635}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":2635,"lines":[{"gurmukhi":"ਬ ਸ਼ੋਰਸ਼ ਦਰਾਮਦ ਸਰਾਫ਼ੀਲ ਸੂਰ।","roman":"Ba shorash daraamad saraafeel soor |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਤਨੇ ਖ਼ਾਸ ਹੂਰ। ੧੬੫।","roman":"Ba rakhash andar aamad tane khaas hoor | 165 |","meaning_en":"","page":2635}]},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":2635,"lines":[{"gurmukhi":"ਬ ਸ਼ੋਰਸ਼ ਦਰਾਮਦ ਜ਼ਿ ਤਨ ਦਰ ਖ਼ਰੋਸ਼।","roman":"Ba shorash daraamad zi tan dar kharosh |","meaning_en":"","page":2635},{"gurmukhi":"ਬ ਬਾਜੂਇ ਮਰਦਾਂ ਬਰਾਵੁਰਦ ਜੋਸ਼। ੧੬੬।","roman":"Ba baajooi mardaan baraavurad josh | 166 |","meaning_en":"","page":2635}]},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":2637,"lines":[{"gurmukhi":"ਯਕੇ ਫ਼ਰਸ਼ ਆਰਾਸਤ ਸੁਰਖ਼ ਅਤਲਸੇ।","roman":"Yake farash aaraasat surakh atalse |","meaning_en":"","page":2637},{"gurmukhi":"ਬੁ ਖ਼ਾਨਦ ਚੁ ਮਕਤਬ ਜ਼ੁਬਾਂ ਪਹਿਲੂਏ। ੧੬੭।","roman":"Bu khaanad chu maktab zubaan pahilooe | 167 |","meaning_en":"","page":2637}]},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":2637,"lines":[{"gurmukhi":"ਬ ਮਰਦਮ ਚੁਨਾ ਕੁਸ਼ਤ ਸ਼ੁਦ ਕਾਰਜ਼ਾਰ।","roman":"Ba mardam chunaa kushat shud kaarzaar |","meaning_en":"","page":2637},{"gurmukhi":"ਜ਼ੁਬਾਂ ਦਰ ਗੁਜ਼ਾਰਮ ਨਿਯਾਯਦ ਸ਼ੁਮਾਰ। ੧੬੮।","roman":"Zubaan dar guzaaram niyaayad shumaar | 168 |","meaning_en":"","page":2637}]},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":2637,"lines":[{"gurmukhi":"ਗੁਰੇਜ਼ਾ ਸ਼ਵਦ ਸ਼ਾਹਿ ਮਾਯੰਦਰਾਂ।","roman":"Gurezaa shavad shaahi maayandraan |","meaning_en":"","page":2637},{"gurmukhi":"ਬ ਕੁਸ਼ਤੰਦ ਲਸ਼ਕਰ ਗਿਰਾਂ ਤਾ ਗਿਰਾਂ। ੧੬੯।","roman":"Ba kushtand lashkar giraan taa giraan | 169 |","meaning_en":"","page":2637}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":2637,"lines":[{"gurmukhi":"ਕਿ ਪੁਸ਼ਤਸ਼ ਬਿਅਫ਼ਤਾਦ ਦੁਖ਼ਤਰ ਵਜ਼ੀਰ।","roman":"Ki pushtash biaftaad dukhtar vazeer |","meaning_en":"","page":2637},{"gurmukhi":"ਬਿ ਬਸਤੰਦ ਓ ਰਾ ਕਿ ਕਰਦੰਦ ਅਸੀਰ।੧੭੦।","roman":"Bi bastand o raa ki kardand aseer | 170 |","meaning_en":"","page":2637}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":2637,"lines":[{"gurmukhi":"ਬ ਨਿਜ਼ਦੇ ਬਿਯਾਵੁਰਦ ਜੋ ਸ਼ਾਹ ਖ਼ੇਸ਼।","roman":"Ba nizde biyaavurad jo shaah khesh |","meaning_en":"","page":2637},{"gurmukhi":"ਬਿ ਗੁਫ਼ਤਹ ਕਿ ਏ ਸ਼ਾਹ ਸ਼ਾਹਾਨ ਵੇਸ਼। ੧੭੧।","roman":"Bi guftah ki e shaah shaahaan vesh | 171 |","meaning_en":"","page":2637}]},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":2637,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਈਂ ਸ਼ਾਹ ਮਾਯੰਦਰਾਂ।","roman":"Bigoyad ki een shaah maayandraan |","meaning_en":"","page":2637},{"gurmukhi":"ਬਿ ਬਸਤਹ ਬਿਯਾਵੁਰਦ ਨਿਜ਼ਦੇ ਸ਼ੁਮਾਂ। ੧੭੨।","roman":"Bi bastah biyaavurad nizde shumaan | 172 |","meaning_en":"","page":2637}]},{"type":"verse","number":[173],"number_text":"੧੭੩।","page":2637,"lines":[{"gurmukhi":"ਅਗਰ ਤੋ ਬਿਗੋਈ ਬ ਜ਼ਾਂ ਈਂ ਬੁਰਮ।","roman":"Agar to bigoee ba zaan een buram |","meaning_en":"","page":2637},{"gurmukhi":"ਵਗਰ ਤੋ ਬਿਗੋਈ ਬ ਜ਼ਿੰਦਾ ਦਿਹਮ। ੧੭੩।","roman":"Vagar to bigoee ba zindaa diham | 173 |","meaning_en":"","page":2637}]},{"type":"verse","number":[174],"number_text":"੧੭੪।","page":2637,"lines":[{"gurmukhi":"ਬਜ਼ਿੰਦਾਂ ਸਪੁਰਦੰਦ ਓ ਰਾ ਅਜ਼ੀਮ।","roman":"Bazindaan sapurdand o raa azeem |","meaning_en":"","page":2637},{"gurmukhi":"ਸਿਤਾਨਦ ਅਜ਼ੋ ਤਾਜ ਸ਼ਾਹੀ ਕਲੀਮ। ੧੭੪।","roman":"Sitaanad azo taaj shaahee kaleem | 174 |","meaning_en":"","page":2637}]},{"type":"verse","number":[175],"number_text":"੧੭੫।","page":2637,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਗੀ ਯਾਫ਼ਤ ਹੁਕਮੋ ਰਜ਼ਾਕ।","roman":"Shahinshaahgee yaafat hukmo razaak |","meaning_en":"","page":2637},{"gurmukhi":"ਕਸੇ ਦੁਸ਼ਮਨਾ ਰਾ ਕੁਨਦ ਚਾਕ ਚਾਕ। ੧੭੫।","roman":"Kase dushamnaa raa kunad chaak chaak | 175 |","meaning_en":"","page":2637}]},{"type":"verse","number":[176],"number_text":"੧੭੬।","page":2637,"lines":[{"gurmukhi":"ਚੁਨਾ ਕਰਦ ਸ਼ੁਦ ਕਸਦ ਮਿਹਨਤ ਕਸੇ।","roman":"Chunaa karad shud kasad mihnat kase |","meaning_en":"","page":2637},{"gurmukhi":"ਕਿ ਰਹਮਤ ਬਬਖ਼ਸ਼ੀਦ ਜੋ ਰਹਮਤੇ। ੧੭੬।","roman":"Ki rahmat babakhsheed jo rahamte | 176 |","meaning_en":"","page":2637}]},{"type":"verse","number":[177],"number_text":"੧੭੭।","page":2637,"lines":[{"gurmukhi":"ਕਿ ਓ ਸ਼ਾਹ ਬਾਨੂ ਸ਼ੁਦੋ ਮੁਲਕ ਸ਼ਾਹ।","roman":"Ki o shaah baanoo shudo mulak shaah |","meaning_en":"","page":2637},{"gurmukhi":"ਕਿ ਸ਼ਾਹੀ ਹਮੀ ਯਾਫ਼ਤ ਹੁਕਮੇ ਇਲਾਹ। ੧੭੭।","roman":"Ki shaahee hamee yaafat hukme ilaah | 177 |","meaning_en":"","page":2637}]},{"type":"verse","number":[178],"number_text":"੧੭੮।","page":2637,"lines":[{"gurmukhi":"ਬਿਦਿਹ ਸਾਕੀਯਾ ਸਾਗਰੇ ਸਬਜ਼ ਆਬ।","roman":"Bidih saakeeyaa saagre sabaz aab |","meaning_en":"","page":2637},{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਬਿਅਫ਼ਤਾਦ ਪਰਦਹ ਨਕਾਬ। ੧੭੮।","roman":"Ki beroon biaftaad pardah nakaab | 178 |","meaning_en":"","page":2637}]},{"type":"verse","number":[179,10],"number_text":"੧੭੯। ੧੦।","page":2637,"lines":[{"gurmukhi":"ਬਿਦਿਹ ਸਾਕੀਯਾ ਸਬਜ਼ ਰੰਗੇ ਫ਼ਿਰੰਗ।","roman":"Bidih saakeeyaa sabaz range firang |","meaning_en":"","page":2637},{"gurmukhi":"ਕਿ ਵਕਤੇ ਬ ਕਾਰ ਅਸਤ ਅਜ਼ ਰੋਜ਼ ਜੰਗ। ੧੭੯। ੧੦।","roman":"Ki vakte ba kaar asat az roz jang | 179 | 10 |","meaning_en":"","page":2637}]}],"ending":null});
